sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_amount;
uniform float amzp_softness;
uniform float amzp_s1On;
uniform float amzp_s1Tool;
uniform float2 amzp_s1From;
uniform float2 amzp_s1To;
uniform float amzp_s1Rad;
uniform float amzp_s1Str;
uniform float amzp_s2On;
uniform float amzp_s2Tool;
uniform float2 amzp_s2From;
uniform float2 amzp_s2To;
uniform float amzp_s2Rad;
uniform float amzp_s2Str;
uniform float amzp_s3On;
uniform float amzp_s3Tool;
uniform float2 amzp_s3From;
uniform float2 amzp_s3To;
uniform float amzp_s3Rad;
uniform float amzp_s3Str;
uniform float amzp_s4On;
uniform float amzp_s4Tool;
uniform float2 amzp_s4From;
uniform float2 amzp_s4To;
uniform float amzp_s4Rad;
uniform float amzp_s4Str;
uniform float amzp_s5On;
uniform float amzp_s5Tool;
uniform float2 amzp_s5From;
uniform float2 amzp_s5To;
uniform float amzp_s5Rad;
uniform float amzp_s5Str;
uniform float amzp_s6On;
uniform float amzp_s6Tool;
uniform float2 amzp_s6From;
uniform float2 amzp_s6To;
uniform float amzp_s6Rad;
uniform float amzp_s6Str;
uniform float amzp_steps;
uniform float amzp_overdrawOn;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float2x2 rot2(float a) { float c = cos(a), s = sin(a); return float2x2(c, s, -s, c); }
    float2 stroke(float2 q, int tool, float2 fp, float2 tp, float rad, float str, float2 W, float pxs, float so, float n) {
        float2 F = W * 0.5 + float2(fp.x, -fp.y) * pxs;
        float R = max(rad, 1.0) * pxs;
        float s = str * amzp_amount;
        if (tool == 0) {
            float2 T = W * 0.5 + float2(tp.x, -tp.y) * pxs;
            float2 D = (T - F) * s;
            float dd = max(dot(D, D), 1e-4);
            for (int k = 0; k < 24; k++) {
                if (float(k) >= n) break;
                float t = clamp(dot(q - F, D) / dd, 0.0, 1.0);
                float dist = length(q - F - D * t);
                float w = 1.0 - smoothstep(R * (1.0 - so), R + 0.5, dist);
                q -= D / n * w;
            }
            return q;
        }
        float2 d = q - F;
        float r = length(d) / R;
        if (r >= 1.0) return q;
        float f = 1.0 - r * r;
        float w = f * f;
        if (tool == 1) return F + rot2(-s * 3.14159265 * w) * d;
        if (tool == 2) return F + d * (1.0 + s * w);
        return F + d * max(1.0 - s * w, 0.05);
    }
    void nmMain() {
        float2 W = layer;
        float2 p = amzLayerNorm() * W;
        float pxs = screen.zw.x / max(screen.zw.x, 1.0);
        float so = clamp(amzp_softness, 0.0, 1.0);
        float n = clamp(floor(amzp_steps + 0.5), 1.0, 24.0);
        float2 q = p;
        if ((amzp_s6On>0.5)) q = stroke(q, int(amzp_s6Tool), amzp_s6From, amzp_s6To, amzp_s6Rad, amzp_s6Str, W, pxs, so, n);
        if ((amzp_s5On>0.5)) q = stroke(q, int(amzp_s5Tool), amzp_s5From, amzp_s5To, amzp_s5Rad, amzp_s5Str, W, pxs, so, n);
        if ((amzp_s4On>0.5)) q = stroke(q, int(amzp_s4Tool), amzp_s4From, amzp_s4To, amzp_s4Rad, amzp_s4Str, W, pxs, so, n);
        if ((amzp_s3On>0.5)) q = stroke(q, int(amzp_s3Tool), amzp_s3From, amzp_s3To, amzp_s3Rad, amzp_s3Str, W, pxs, so, n);
        if ((amzp_s2On>0.5)) q = stroke(q, int(amzp_s2Tool), amzp_s2From, amzp_s2To, amzp_s2Rad, amzp_s2Str, W, pxs, so, n);
        if ((amzp_s1On>0.5)) q = stroke(q, int(amzp_s1Tool), amzp_s1From, amzp_s1To, amzp_s1Rad, amzp_s1Str, W, pxs, so, n);
        bool pin = p.x >= 0.0 && p.y >= 0.0 && p.x <= W.x && p.y <= W.y;
        bool qin = q.x >= 0.0 && q.y >= 0.0 && q.x <= W.x && q.y <= W.y;
        if (!qin && ((amzp_overdrawOn>0.5) || !pin)) { amzOutput = float4(0.0); return; }
        amzOutput = amzTexture(0, l2s(clamp(q / W, 0.0, 1.0)));
    }
    void amzRender() {
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
